// Rang dans l'échelle : ordre de déclaration dans la famille
const rungCounter = {};
CALI_EXERCISES.forEach((e) => {
  rungCounter[e.family] = (rungCounter[e.family] || 0) + 1;
  e.rung = rungCounter[e.family];
});

